let data = actions.findorder;

function isInHeaderType(...params) {
  return data.headerMessages.some(x =>
    params.some(param =>
      x.type?.toLowerCase() === param.toLowerCase()
    )
  );
}

function hasDyOrD8Carrier(order) {
  const targetCarriers = ["DY", "D8"];

  // Check all trip segments
  const hasMatchingSegment =
    order?.customerTrip?.bounds?.some(bound =>
      bound?.segments?.some(segment =>
        targetCarriers.includes(segment?.marketingCarrier?.code) ||
        targetCarriers.includes(segment?.operatingCarrier?.code)
      )
    );

  // Check validating carriers array
  const hasMatchingValidatingCarrier =
    order?.validatingCarriers?.some(code =>
      targetCarriers.includes(code)
    );

  // Check provider booking details validating carrier
  const hasMatchingProviderValidatingCarrier =
    order?.orderProviderBookingDetails?.some(detail =>
      targetCarriers.includes(detail?.validatingCarrier?.code)
    );

  return (
    hasMatchingSegment ||
    hasMatchingValidatingCarrier ||
    hasMatchingProviderValidatingCarrier
  );
}

ZT.setFormData("isSpecialCarrier", hasDyOrD8Carrier(data));
ZT.setFormData("hasFlexibleTicket", data.hasFlexibleTicket?.toString())
ZT.setFormData("hasChargeback", data.hasChargeback.toString())
ZT.setFormData("currency", data.currency)
ZT.setFormData("cc2c", isInHeaderType("cc2c", "CC2_CARRIER") ? "Yes" : "No")
ZT.setFormData("isWenrix",isInHeaderType("wenrix") ? "Yes" : "No" )
ZT.setFormData("isShowFlexibleTicket", data.hasFlexibleTicket?.toString() == "true" && data.flexibleTicketUsed?.toString() == "false")
ZT.setFormData("update_ticket_tag", "zt_flow_used")

ZT.setTransformData("html_alert_message", "");
